file.content:
.summary-panel {
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border-hairline);
  border-radius: var(--radius-md);
  box-shadow: 0 -2px 8px rgba(33, 29, 24, 0.08);
}

.summary-panel__sold-out {
  margin: 0;
  padding: var(--spacing-4);
  color: var(--color-ink-secondary);
}

.summary-panel__toggle {
  display: flex;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-3) var(--spacing-4);
  background: none;
  border: none;
  cursor: pointer;
  font: inherit;
  color: var(--color-ink-primary);
}

.summary-panel__toggle-total {
  font-family: var(--font-display);
  font-size: var(--text-display-sm-size);
  font-weight: var(--text-display-sm-weight);
}

.summary-panel__content {
  display: none;
  padding: 0 var(--spacing-4) var(--spacing-4);
}

.summary-panel--expanded .summary-panel__content {
  display: block;
}

@media (max-width: 767.98px) {
  .summary-panel--expanded .summary-panel__content {
    display: flex;
    flex-direction: column;
    max-height: 60vh;
  }

  .summary-panel--expanded .summary-panel__list {
    overflow-y: auto;
    min-height: 0;
  }
}

.summary-panel__list {
  list-style: none;
  margin: 0 0 var(--spacing-3);
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-2);
}

.summary-panel__item {
  display: flex;
  justify-content: space-between;
  gap: var(--spacing-2);
  font-size: var(--text-body-size);
}

.summary-panel__item-category {
  color: var(--color-ink-secondary);
}

.summary-panel__empty {
  color: var(--color-ink-secondary);
  margin: 0 0 var(--spacing-3);
}

.summary-panel__total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: var(--spacing-3);
  border-top: 1px solid var(--color-border-hairline);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
}

.summary-panel__total-amount {
  font-family: var(--font-display);
  font-size: var(--text-display-sm-size);
  font-weight: var(--text-display-sm-weight);
}

@media (min-width: 768px) {
  .summary-panel {
    box-shadow: 0 1px 4px rgba(33, 29, 24, 0.06);
  }

  .summary-panel__toggle {
    display: none;
  }

  .summary-panel__content {
    display: block;
    padding: var(--spacing-4);
  }
}

@if (loadError()) {
  <p class="sitzplan-page__error" role="alert">Sitzplan konnte nicht geladen werden.</p>
} @else if (seatMap(); as map) {
  <div class="sitzplan-page__layout">
    <div
      class="sitzplan-page__viewport"
      (wheel)="onWheel($event)"
      (pointerdown)="onPointerDown($event)"
      (pointermove)="onPointerMove($event)"
      (pointerup)="onPointerUp($event)"
      (pointercancel)="onPointerUp($event)"
    >
      <div
        class="sitzplan-page__grid"
        [style.grid-template-columns]="'auto repeat(' + map.columns + ', minmax(32px, 1fr))'"
        [style.transform]="transform()"
        (keydown)="onGridKeydown($event)"
      >
        <span class="sitzplan-page__corner"></span>
        @for (column of columnNumbers(); track column) {
          <span class="sitzplan-page__column-label">{{ column }}</span>
        }
        @for (rowGroup of rowsWithCells(); track rowGroup.row) {
          <span class="sitzplan-page__row-label">{{ rowGroup.row }}</span>
          @for (cell of rowGroup.cells; track $index) {
            @if (cell.seat; as seat) {
              <app-seat
                [row]="seat.row"
                [column]="seat.column"
                [status]="seat.status"
                [selected]="selectedSeatIds().has(seat.seatId)"
                [focused]="focusedSeatId() === seat.seatId"
                [categoryName]="categoryOf(seat.seatId)?.name ?? null"
                [categoryPrice]="categoryOf(seat.seatId)?.price ?? null"
                (toggled)="onSeatToggled(seat.seatId)"
              />
            } @else {
              <div class="sitzplan-page__aisle"></div>
            }
          }
          @if (panelSeatId(); as seatId) {
            @if (rowGroup.row === panelSeatRow()) {
              <app-price-category-panel
                class="sitzplan-page__price-panel"
                [categories]="priceCategories()"
                [selectedCategoryId]="assignedCategoryId().get(seatId) ?? null"
                (categorySelected)="onCategoryChosen(seatId, $event)"
              />
            }
          }
        }
      </div>
    </div>

    <app-summary-panel
      class="sitzplan-page__summary"
      [seats]="selectedSeatSummaries()"
      [totalPrice]="totalPrice()"
      [soldOut]="soldOut()"
    />
  </div>
} @else {
  <div
    class="sitzplan-page__grid sitzplan-page__grid--placeholder"
    [style.grid-template-columns]="'repeat(' + placeholderColumns + ', minmax(32px, 1fr))'"
    aria-busy="true"
    aria-label="Sitzplan wird geladen"
  >
    @for (cell of placeholderCells; track $index) {
      <div class="sitzplan-page__placeholder-cell"></div>
    }
  </div>
}

