            .Select(pc => new PriceCategoryDto(pc.Id, pc.Name, pc.Preis))
            .ToListAsync();

        return new SeatMapDto(eventId, room.Reihen, room.SpaltenAnzahl, room.GangSpalten, seats, priceCategories);
